Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Definition MBElems (m : mem) (es : list mbe) : Prop :=
  forall x s, In (x, s) es -> exists junk, rw_cells rsegs m (x + 16) [C8 (wz s); CB (Z.to_nat s) junk].

(* [comment removed for export] *)
Definition mb_addr_ok (b : Z) (es : list mbe) : Prop :=
  (forall x s, In (x, s) es -> 0 < x /\ x mod 16 = 0 /\ 0 <= s /\ x + 24 + s <= hceil)
  /\ (forall x1 s1 x2 s2, In (x1, s1) es -> In (x2, s2) es -> x1 <> x2 -> x1 + 24 + s1 <= x2 \/ x2 + 24 + s2 <= x1)
  /\ hceil <= b /\ b + 64 <= 2^64 /\ b mod 8 = 0.

(* [comment removed for export] *)
Definition MBraw (m : mem) (b : Z) (es : list mbe) (out insz outpos outend : Z) : Prop :=
  exists ls : LS,
    rw_cells rsegs m b [C8 (wz MB_MAX)]
    /\ rw_cells rsegs m (b + 24) [C8 (wz out); C8 (wz insz); C8 (wz 0); C8 (wz outpos); C8 (wz outend)]
    /\ dl_ok (b + 8) (map fst es) ls /\ LSCells m ls /\ MBElems m es /\ mb_addr_ok b es.

(* [comment removed for export] *)
Definition MBuf (m : mem) (b : Z) (es : list mbe) (insz : Z) : Prop :=
  MBraw m b es (mb_out b es insz) insz (mb_outpos es insz) (mb_outpos es insz) /\ mb_ok es insz.

(* [comment removed for export] *)
Definition MBufOwn (LB : list block) (es : list mbe) : Prop :=
  forall x s, In (x, s) es -> exists p, In (p, x, mb_block_size s) LB.

(* [comment removed for export] *)
Fixpoint mb_elemsW (es : list mbe) : list (Z * Z) :=
  match es with [] => [] | (x, s) :: es' => (x, x + 24 + s) :: mb_elemsW es' end.

