Lemma MBElems_lookup : forall m es x s, MBElems m es -> In (x, s) es ->
  exists junk, rw_cells rsegs m (x + 16) [C8 (wz s); CB (Z.to_nat s) junk].
Proof. intros m es x s H IN. exact (H x s IN). Qed.

Lemma MBElems_nil : forall m, MBElems m [].
Proof. intros m x s []. Qed.

Lemma MBElems_transport : forall W m m' es,
  MBElems m es -> munch W m m' -> wmono rsegs m m' ->
  (forall x s, In (x, s) es -> 0 <= s /\ disjoint_from W (x + 16) (8 + s)) -> MBElems m' es.
Proof.
  intros W m m' es H MU WM D x s IN. destruct (H x s IN) as [junk C]. exists junk.
  destruct (D x s IN) as [S0 DX].
  eapply rw_cells_transport; [exact C| exact MU| exact WM|]. cbn [cells_size csize]. rewrite Nat.add_0_r, Nat2Z.inj_add, Z2Nat.id by lia. exact DX.
Qed.

