Lemma MBElems_update : forall W m m' b es x s junk',
  MBElems m es -> mb_addr_ok b es -> NoDup (map fst es) -> In (x, s) es ->
  munch W m m' -> wmono rsegs m m' ->
  (forall x2 s2, In (x2, s2) es -> x2 <> x -> disjoint_from W (x2 + 16) (8 + s2)) ->
  rw_cells rsegs m' (x + 16) [C8 (wz s); CB (Z.to_nat s) junk'] ->
  MBElems m' es.
Proof.
  intros W m m' b es x s junk' H (AD & DJ & _) ND IN MU WM D C x2 s2 IN2.
  destruct (Z.eq_dec x2 x) as [->|NE].
  - rewrite (mb_In_unique es x s2 s ND IN2 IN). exists junk'. exact C.
  - destruct (H x2 s2 IN2) as [j2 C2]. exists j2. destruct (AD x2 s2 IN2) as (_ & _ & S2 & _).
    eapply rw_cells_transport; [exact C2| exact MU| exact WM|]. cbn [cells_size csize]. rewrite Nat.add_0_r, Nat2Z.inj_add, Z2Nat.id by lia.
    exact (D x2 s2 IN2 NE).
Qed.

