Lemma mb_data_join3 : forall m x s o l j1 bs j3,
  rw_cells rsegs m (x + 16) [C8 (wz s)] -> rw_cells rsegs m (x + 24) [CB (Z.to_nat o) j1] ->
  rw_cells rsegs m (x + 24 + o) [CB (Z.to_nat l) bs] -> rw_cells rsegs m (x + 24 + o + l) [CB (Z.to_nat (s - o - l)) j3] ->
  0 <= o -> 0 <= l -> o + l <= s ->
  rw_cells rsegs m (x + 16) [C8 (wz s); CB (Z.to_nat s) (j1 ++ bs ++ j3)].
Proof.
  intros m x s o l j1 bs j3 HS H1 H2 H3 Ho Hl Hs.
  pose proof (rw_cells_CB_join rsegs _ _ _ _ _ _ H2 ltac:(rewrite Z2Nat.id by lia; exact H3)) as H23.
  pose proof (rw_cells_CB_join rsegs _ _ _ _ _ _ H1 ltac:(rewrite Z2Nat.id by lia; exact H23)) as H123.
  replace (Z.to_nat o + (Z.to_nat l + Z.to_nat (s - o - l)))%nat with (Z.to_nat s) in H123 by lia.
  apply (proj2 (rw_cells_app rsegs m (x + 16) [C8 (wz s)] [CB (Z.to_nat s) (j1 ++ bs ++ j3)])).
  cbn [cells_size csize Nat.add]. replace (x + 16 + Z.of_nat 8) with (x + 24) by lia. split; [exact HS| exact H123].
Qed.

