Lemma mb_addr_ok_nil : forall b, hceil <= b -> b + 64 <= 2^64 -> b mod 8 = 0 -> mb_addr_ok b [].
Proof.
  intros b H1 H2 H3. split; [intros x s []|]. split; [intros x1 s1 x2 s2 []|]. split; [exact H1|]. split; [exact H2| exact H3].
Qed.
