Lemma mb_addr_ok_elem : forall b es x s, mb_addr_ok b es -> In (x, s) es ->
  0 < x /\ x mod 16 = 0 /\ 0 <= s /\ x + 24 + s <= hceil /\ x + 24 + s <= b.
Proof. intros b es x s (AD & _ & HB & _) IN. destruct (AD x s IN) as (P & Q & R & T). lia. Qed.

(* [comment removed for export] *)
Lemma mb_lnode : forall m hL L ls x, dl_ok hL L ls -> LSCells m ls -> x ∈ hL :: L ->
  exists nd, ls !! x = Some nd /\ l_next nd = cnext hL L x /\ l_prev nd = cprev hL L x
             /\ rw_cells rsegs m x [C8 (wz (cnext hL L x)); C8 (wz (cprev hL L x))].
Proof.
  intros m hL L ls x DL LC IN. destruct (dl_lookup _ _ _ DL x IN) as (nd & Lx & N & P).
  exists nd. split; [exact Lx|]. split; [exact N|]. split; [exact P|].
  pose proof (LSCells_lookup _ _ _ _ LC Lx) as C. unfold LNodeCells in C. rewrite N, P in C. exact C.
Qed.

(* [comment removed for export] *)
Lemma mb_root_node : forall m b (es : list mbe) ls, dl_ok (b + 8) (map fst es) ls -> LSCells m ls ->
  rw_cells rsegs m (b + 8) [C8 (wz (lhead (b + 8) (map fst es))); C8 (wz (mb_lasta b es))].
Proof.
  intros m b es ls DL LC.
  destruct (mb_lnode m _ _ _ (b + 8) DL LC ltac:(rewrite elem_of_cons; left; reflexivity)) as (nd & _ & _ & _ & C).
  rewrite cnext_hd, cprev_hd in C.
  replace (llast (b + 8) (map fst es)) with (mb_lasta b es) in C; [exact C|].
  unfold mb_lasta, llast. clear. induction es as [|[x s] es IH] using rev_ind. { reflexivity. }
  rewrite map_app. cbn [map fst]. rewrite !last_last. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma mb_elem_node : forall m b (es A B : list mbe) x s ls,
  dl_ok (b + 8) (map fst es) ls -> LSCells m ls -> es = A ++ (x, s) :: B ->
  rw_cells rsegs m x [C8 (wz (lhead (b + 8) (map fst B))); C8 (wz (llast (b + 8) (map fst A)))].
Proof.
