Proof. intros d [|[x s] R] T NE; [exfalso; exact (NE eq_refl)| reflexivity]. Qed.

(* [comment removed for export] *)
Lemma mb_ls_sep : forall b (es : list mbe) ls, dl_ok (b + 8) (map fst es) ls -> mb_addr_ok b es -> ls_sep ls.
Proof.
  intros b es ls DL AOK a c na nc La Lc NE.
  destruct DL as (N & DOM & _). pose proof AOK as (AD & DJ & HB & _).
  assert (Ia : a ∈ (b + 8) :: map fst es) by (apply DOM; rewrite La; eexists; reflexivity).
  assert (Ic : c ∈ (b + 8) :: map fst es) by (apply DOM; rewrite Lc; eexists; reflexivity).
  rewrite elem_of_cons in Ia, Ic.
  assert (EL : forall y, y ∈ map fst es -> exists s, In (y, s) es).
  { intros y Hy. apply list_elem_of_In in Hy. apply in_map_iff in Hy. destruct Hy as ([y' s] & E & IN). cbn in E. subst y'. exists s. exact IN. }
  destruct Ia as [->|Ia]; destruct Ic as [->|Ic].
  - exfalso. exact (NE eq_refl).
  - destruct (EL c Ic) as [sc Icc]. destruct (AD c sc Icc) as (_ & _ & S0 & R). lia.
  - destruct (EL a Ia) as [sa Iaa]. destruct (AD a sa Iaa) as (_ & _ & S0 & R). lia.
  - destruct (EL a Ia) as [sa Iaa]. destruct (EL c Ic) as [sc Icc].
    destruct (AD a sa Iaa) as (_ & _ & Sa & _). destruct (AD c sc Icc) as (_ & _ & Sc & _).
    destruct (DJ a sa c sc Iaa Icc NE); lia.
Qed.

