Lemma mb_lnode_cases : forall b (es : list mbe) ls a n, dl_ok (b + 8) (map fst es) ls -> mb_addr_ok b es ->
  ls !! a = Some n -> a = b + 8 \/ exists s, In (a, s) es /\ 0 < a /\ a mod 16 = 0 /\ 0 <= s /\ a + 24 + s <= hceil.
Proof.
  intros b es ls a n DL AOK La. destruct DL as (N & DOM & _). pose proof AOK as (AD & _).
  assert (Ia : a ∈ (b + 8) :: map fst es) by (apply DOM; rewrite La; eexists; reflexivity).
  rewrite elem_of_cons in Ia. destruct Ia as [E|Ia]; [left; exact E| right].
  apply list_elem_of_In in Ia. apply in_map_iff in Ia. destruct Ia as ([a' s] & E & IN). cbn in E. subst a'.
  exists s. split; [exact IN|]. exact (AD a s IN).
Qed.

