(* [comment removed for export] *)
Lemma MBraw_set_header : forall W m m' b es out insz outpos outend out' insz' outpos' outend',
  MBraw m b es out insz outpos outend -> munch W m m' -> wmono rsegs m m' ->
  disjoint_from W b 24 -> (forall x s, In (x, s) es -> disjoint_from W x (24 + s)) ->
  rw_cells rsegs m' (b + 24) [C8 (wz out'); C8 (wz insz'); C8 (wz 0); C8 (wz outpos'); C8 (wz outend')] ->
