Lemma MBuf_transport : forall SP W m m' b es insz,
  MBuf m b es insz -> munch W m m' -> wmono rsegs m m' -> stackW SP W -> SP <= b -> MBuf m' b es insz.
Proof. intros SP W m m' b es insz [R OK] MU WM SW LE. split; [| exact OK]. eapply MBraw_transport; eauto. Qed.

