Lemma mb_push_back : forall W m m' hL L ls x,
  dl_ok hL L ls -> LSCells m ls -> munch W m m' -> wmono rsegs m m' ->
  x <> 0 -> x ∉ hL :: L -> 0 <= x < 2^64 -> 0 <= hL < 2^64 ->
  (forall a n, ls !! a = Some n -> a <> hL -> a <> llast hL L -> disjoint_from W a 16) ->
  rw_cells rsegs m' hL [C8 (wz (lhead hL (L ++ [x]))); C8 (wz x)] ->
  rw_cells rsegs m' x [C8 (wz hL); C8 (wz (llast hL L))] ->
  (L <> [] -> rw_cells rsegs m' (llast hL L) [C8 (wz x); C8 (wz (cprev hL L (llast hL L)))]) ->
  exists ls', dl_ok hL (L ++ [x]) ls' /\ LSCells m' ls'.
