Lemma MBraw_snoc_nil : forall W m m' b out insz outpos outend x g junk out' outend',
  MBraw m b [] out insz outpos outend -> munch W m m' -> wmono rsegs m m' ->
  disjoint_from W b 8 ->
  rw_cells rsegs m' (b + 24) [C8 (wz out'); C8 (wz insz); C8 (wz 0); C8 (wz outpos); C8 (wz outend')] ->
  rw_cells rsegs m' (b + 8) [C8 (wz x); C8 (wz x)] ->
  rw_cells rsegs m' x [C8 (wz (b + 8)); C8 (wz (b + 8))] ->
  rw_cells rsegs m' (x + 16) [C8 (wz g); CB (Z.to_nat g) junk] ->
  0 < x -> x mod 16 = 0 -> 0 <= g -> x + 24 + g <= hceil ->
  MBraw m' b [(x, g)] out' insz outpos outend'.
