Scheme kc__7 := Elimination for Corelib.Init.Datatypes.list Sort Prop.

Lemma MBraw_snoc_cons : forall W m m' b (P : list mbe) xl sl out insz outpos outend x g junk out' outend',
  MBraw m b (P ++ [(xl, sl)]) out insz outpos outend -> munch W m m' -> wmono rsegs m m' ->
  disjoint_from W b 8 ->
  (forall x' s', In (x', s') (P ++ [(xl, sl)]) -> disjoint_from W (x' + 16) (8 + s')) ->
  (forall x' s', In (x', s') P -> disjoint_from W x' 16) ->
  rw_cells rsegs m' (b + 24) [C8 (wz out'); C8 (wz insz); C8 (wz 0); C8 (wz outpos); C8 (wz outend')] ->
  rw_cells rsegs m' (b + 8) [C8 (wz (fst (hd (0, 0) (P ++ [(xl, sl)])))); C8 (wz x)] ->
  rw_cells rsegs m' x [C8 (wz (b + 8)); C8 (wz xl)] ->
  rw_cells rsegs m' xl [C8 (wz x); C8 (wz (llast (b + 8) (map fst P)))] ->
  rw_cells rsegs m' (x + 16) [C8 (wz g); CB (Z.to_nat g) junk] ->
  0 < x -> x mod 16 = 0 -> 0 <= g -> x + 24 + g <= hceil ->
  (forall x' s', In (x', s') (P ++ [(xl, sl)]) -> x + 24 + g <= x' \/ x' + 24 + s' <= x) ->
  MBraw m' b ((P ++ [(xl, sl)]) ++ [(x, g)]) out' insz outpos outend'.
