(* [comment removed for export] *)
Lemma MBuf_init : forall m b,
  rw_cells rsegs m b (MBufHdrCells (b + 8) (b + 8) (b + 8) 0 0 0 0) ->
  hceil <= b -> b + 64 <= 2^64 -> b mod 8 = 0 -> MBuf m b [] 0.
Proof.
  intros m b H HC HB AL. hcb. unfold MBufHdrCells in H.
  pose proof (proj1 (rw_cells_app rsegs m b [C8 (wz 0x1fffffffffffffff)] _) H) as [H0 H']. cbn [cells_size csize Nat.add] in H'.
  pose proof (proj1 (rw_cells_app rsegs m (b + Z.of_nat 8) [C8 (wz (b + 8)); C8 (wz (b + 8))] _) H') as [HR H1].
  cbn [cells_size csize Nat.add] in H1. replace (b + Z.of_nat 8 + Z.of_nat 16) with (b + 24) in H1 by lia.
  replace (b + Z.of_nat 8) with (b + 8) in HR by lia.
  split; [| exact mb_ok_nil].
  exists {[ b + 8 := init_lheader_node (b + 8) ]}. split; [exact H0|]. split.
  { unfold mb_out, mb_outpos. cbn. exact H1. }
  split. { cbn [map]. apply dl_ok_empty. lia. }
  split. { intros a n L. rewrite lookup_singleton_Some in L. destruct L as [<- <-].
           split; [unfold lnode_wf; cbn [l_next l_prev init_lheader_node]; lia| exact HR]. }
  split; [apply MBElems_nil| apply mb_addr_ok_nil; assumption].
Qed.

(* [comment removed for export] *)
Lemma MBufOwn_nil : forall LB, MBufOwn LB [].
Proof. intros LB x s []. Qed.

Lemma MBufOwn_cons_LB : forall LB blk es, MBufOwn LB es -> MBufOwn (blk :: LB) es.
Proof. intros LB blk es H x s IN. destruct (H x s IN) as [p Hp]. exists p. right. exact Hp. Qed.

Lemma MBufOwn_snoc : forall LB es p x s, MBufOwn LB es -> In (p, x, mb_block_size s) LB -> MBufOwn LB (es ++ [(x, s)]).
Proof.
  intros LB es p x s H HIN x2 s2 IN. apply in_app_iff in IN. destruct IN as [IN|[E|[]]]; [exact (H x2 s2 IN)|].
  injection E as -> ->. exists p. exact HIN.
Qed.

